using ChartForgeX.Interactivity.Html;
using ChartForgeX.Typography;
internal static class NativeJointStackValueExamples {
    internal static void Write(string output,string[] args){var font=NativeFallbackRadialExamples.RequiredFont(args,"--primary-font");FontRegistry.Register("Native joint-stack font",font);Directory.CreateDirectory(output);var renderer=new HtmlInteractiveChartRenderer();foreach(var variant in new[]{"stacked-bar","default-stacked","normalized-bar"})foreach(var width in new[]{390,760}){var mode=width==390?VisualThemeMode.Light:VisualThemeMode.Dark;Chart Model(double value){var chart=NativeCompleteCartesianValueRecipe.Create(variant=="default-stacked"?"stacked-bar":variant,value,width,mode,"Native joint-stack font");if(variant=="default-stacked"){foreach(var row in chart.Series)row.WithStackGroup(null);chart.WithBarMode(ChartBarMode.Stacked);}return chart;}ChartVisibilityView View(bool hidden)=>new(hidden?new[]{new ChartSeriesId("delivery")}:Array.Empty<ChartSeriesId>(),ChartVisibilityLabelLayering.GroupWithSeries);var from=renderer.PrepareVisibilitySection(Model(30),View(false));var to=renderer.PrepareVisibilitySection(Model(40),View(true));var payload=renderer.PrepareNativeTransitionJson(from,to,new HtmlNativeTransitionOptions(HtmlNativeTransitionEffect.ValuesAndVisibility,5));var prefix=Path.Combine(output,"native-joint-stack-"+variant+"-"+width);File.WriteAllText(prefix+".from.html",from.Html);File.WriteAllText(prefix+".to.html",to.Html);File.WriteAllText(prefix+".transition.json",payload);File.WriteAllText(prefix+".from.svg",from.PreparedVisual.ToSvg());File.WriteAllBytes(prefix+".from.png",from.PreparedVisual.ToPng());File.WriteAllText(prefix+".to.svg",to.PreparedVisual.ToSvg());File.WriteAllBytes(prefix+".to.png",to.PreparedVisual.ToPng());File.WriteAllText(prefix+".program.cs",ExampleRecipeSource.EmitNativeJointStackValue(variant,width,mode));}}
}
